Hmm, this is getting messy. Let me simplify: flush always processes in 800-sample units, and always requires an even count except at the very end where a trailing odd byte is dropped (can't do anything with it).

```c
static int sp_flush_pcm(bool fin)
{
  static int16_t in[800];
  static int16_t outbuf[2400];
  size_t avail = s_sp_pcm_len;
  size_t off = 0;
  int ret;

  if (!fin)
    {
      avail &= ~(size_t)1;    /* 不完整的半采样留到下一块 */
    }
  else
    {
      avail &= ~(size_t)1;    /* 末尾多出的半个采样丢弃 */
    }

  while (off + 2 <= avail)
    {
      size_t n_in = (avail - off) / 2;
      int n_out = 0;
      size_t j;

      if (n_in > 800)
        {
          n_in = 800;
        }

      for (j = 0; j < n_in; j++)
        {
          in[j] = (int16_t)((uint16_t)s_sp_pcm[off + j * 2] |
                            ((uint16_t)s_sp_pcm[off + j * 2 + 1] << 8));
        }

      if (s_sp_rate == 16000)
        {
          ... 3:2 插值 → outbuf, n_out
        }
      else
        {
          ... L=R → outbuf, n_out
        }

      ret = hal_i2s_write_async(outbuf, (uint32_t)n_out * 2);
      if (ret < 0)
        {
          printf("[Voice] 流式播放失败: hal_i2s_write_async=%d (%s)\n",
                 ret, strerror(-ret));
          hal_i2s_write_flush();
          return ret;
        }

      s_sp_i2s = true;
      off += n_in * 2;
    }

  /* 把头尾剩下的字节挪到缓冲开头 */
  if (off > 0)
    {
      memmove(s_sp_pcm, s_sp_pcm + off, s_sp_pcm_len - off);
      s_sp_pcm_len -= off;
    }

  return 0;
}
