Hmm, need a `s_sp_riff_seen` flag. Let me restructure with an explicit state enum:

```c
enum { SP_RIFF = 0, SP_CHUNK, SP_FMT, SP_SKIP, SP_DATA };
static int s_sp_st;
```

States:
- SP_RIFF: need ≥12 bytes in s_sp_hdr. Check "RIFF"/"WAVE". Consume 12. → SP_CHUNK.
- SP_CHUNK: need ≥8. Read id + size. Consume 8.
   - "data" → s_sp_data_bytes = size; → SP_DATA
   - "fmt " → csize → SP_FMT (remember csize)
   - else → s_sp_skip = csize + (csize&1); → SP_SKIP
- SP_FMT: need ≥ (csize ≥ 8 ? 8 : csize) bytes for the rate; consume min(csize,8) ... then skip csize-8+(csize&1). Simplify: need ≥8 bytes → read rate; consume 8; then s_sp_skip = csize - 8 + (csize & 1); → SP_SKIP.
   (Guard csize ≥ 8; if csize < 8 treat as skip csize.)
- SP_SKIP: discard min(len, skip).
- SP_DATA: done → remaining buffer bytes are PCM.

Implementation consuming from s_sp_hdr by memmove.

```c
static int sp_parse(void)
{
  for (;;)
    {
      if (s_sp_st == SP_SKIP)
        {
          size_t n = (s_sp_hdr_len < (size_t)s_sp_skip)
                     ? s_sp_hdr_len : (size_t)s_sp_skip;
          if (n == 0) return 0;
          memmove(s_sp_hdr, s_sp_hdr + n, s_sp_hdr_len - n);
          s_sp_hdr_len -= n;
          s_sp_skip -= (uint32_t)n;
          if (s_sp_skip == 0) s_sp_st = SP_CHUNK;
          continue;
        }

      if (s_sp_st == SP_RIFF)
        {
          if (s_sp_hdr_len < 12) return 0;
          if (memcmp(s_sp_hdr, "RIFF", 4) != 0 ||
              memcmp(s_sp_hdr + 8, "WAVE", 4) != 0)
            {
              printf("[Voice] 流式播放: 不是 RIFF/WAVE（首4字节 %02X %02X %02X %02X）\n",
                     s_sp_hdr[0], s_sp_hdr[1], s_sp_hdr[2], s_sp_hdr[3]);
              return -EINVAL;
            }
          memmove(s_sp_hdr, s_sp_hdr + 12, s_sp_hdr_len - 12);
          s_sp_hdr_len -= 12;
          s_sp_st = SP_CHUNK;
          continue;
        }

      if (s_sp_st == SP_CHUNK)
        {
          uint32_t csize;
          if (s_sp_hdr_len < 8) return 0;
          csize = rd32(s_sp_hdr + 4);
          if (memcmp(s_sp_hdr, "data", 4) == 0)
            {
              s_sp_data_bytes = csize;
              memmove(... +8, -8); s_sp_hdr_len -= 8;
              s_sp_st = SP_DATA;
              return 0;
            }
          else if (memcmp(s_sp_hdr, "fmt ", 4) == 0 && csize >= 8)
            {
              s_sp_fmt_size = csize;
              memmove(..., -8); s_sp_hdr_len -= 8;
              s_sp_st = SP_FMT;
              continue;
            }
          else
            {
              s_sp_skip = csize + (csize & 1);
              memmove(..., -8); s_sp_hdr_len -= 8;
              s_sp_st = (s_sp_skip > 0) ? SP_SKIP : SP_CHUNK;
              continue;
            }
        }

      if (s_sp_st == SP_FMT)
        {
          if (s_sp_hdr_len < 8) return 0;
          s_sp_rate = rd32(s_sp_hdr + 4);
          memmove(..., -8); s_sp_hdr_len -= 8;
          s_sp_skip = s_sp_fmt_size - 8 + (s_sp_fmt_size & 1);
          s_sp_st = (s_sp_skip > 0) ? SP_SKIP : SP_CHUNK;
          continue;
        }

      return 0;   /* SP_DATA */
    }
}
