  tv.tv_usec = (stall_timeout_ms % 1000) * 1000;
  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  addr.sin_family = AF_INET;
  addr.sin_port   = htons(g_sb_port);

  ret = connect(fd, (FAR struct sockaddr *)&addr, sizeof(addr));
  if (ret < 0)
