  ret = send(fd, req, rl, 0);
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  for (;;)
    {
      int n = recv(fd, buf, sizeof(buf) - 1, 0);

      if (n <= 0)
        {
          if (n < 0)
