          memcpy(hdr + hdr_len, buf, (size_t)take);
          hdr_len += take;
          hdr[hdr_len] = '\\0';

          p = strstr(hdr, "\\r\\n\\r\\n");
          if (p == NULL)
            {
              if (hdr_len >= (int)sizeof(hdr) - 1)
                {
