          /* 状态行必须是 200：404/502 的 JSON 体不能当音频播 */

          {
            char *sp = strstr(hdr, " ");

            if (sp == NULL || strncmp(hdr, "HTTP/1.", 7) != 0 ||
                atoi(sp + 1) != 200)
              {
                printf("[Bridge] STREAM %s -> %.48s（非 200，放弃）\\n",
                       path, hdr);
