            }

          if (boff > n)
            {
              boff = n;
            }

          if (n - boff > 0)
            {
              if (max_bytes > 0 && (size_t)(n - boff) > max_bytes)
                {
                  printf("[Bridge] STREAM %s 超过上限 %u B，中止\\n",
                         path, (unsigned)max_bytes);
                  close(fd);
                  return -EIO;
