              if (ret < 0)
                {
                  printf("[Bridge] STREAM %s 回调中止(%d)，已收 %u B\\n",
                         path, ret, (unsigned)total);
                  close(fd);
                  return ret;
                }

              total += (size_t)(n - boff);
            }

