          close(fd);
          return ret;
        }

      total += (size_t)n;
    }

  close(fd);

  if (!header_done)
    {
      printf("[Bridge] STREAM %s 未收到完整响应头\\n", path);
      return -EIO;
    }

  return (int)total;
}

