              uint32_t pos = (uint32_t)j * 2;
              uint32_t i = pos / 3;
              uint32_t frac = pos % 3;
              int16_t a = in[i];
              int16_t b = (i + 1 < (uint32_t)n_in) ? in[i + 1] : a;
              int16_t s;

              if (frac == 0)
