s._dtr_state = False
s._rts_state = False
s.open()

buf = bytearray()
stop = threading.Event()
t0 = time.time()

def reader():
    while not stop.is_set():
        try:
            d = s.read(8192)
        except Exception:
            break
        if d:
            buf.extend(d)

threading.Thread(target=reader, daemon=True).start()

seen = 0
def drain():
    global seen
    raw = bytes(buf)
    txt = raw[seen:].decode('utf-8', 'replace')
    seen = len(raw)
    for line in txt.splitlines():
        if line.strip():
            print('[%7.2fs] %s' % (time.time() - t0, line.strip()))

# 敲一下回车骗出提示符
s.write(b'\\r\\n'); s.flush()
t_ready = None
while time.time() - t0 < 15:
    if b'nsh>' in bytes(buf):
        t_ready = time.time() - t0
        break
    time.sleep(0.05)
drain()
print('[%7.2fs] === 板卡就绪 ===' % (time.time() - t0))
