```c
static FAR void *voice_watchdog(void *arg)
{
  (void)arg;

  for (;;)
    {
      int      st;
      uint32_t el;
      unsigned limit;

      usleep(1000 * 1000);   /* 1s 巡一次：够快，且几乎不占 CPU */

      pthread_mutex_lock(&g_lock);
      st  = g_state;
      el  = (uint32_t)((clock_systime_ticks() - g_phase_tick) * 1000 /
                       TICK_PER_SEC);
      if (!g_busy)
        {
          pthread_mutex_unlock(&g_lock);
          continue;
        }
      pthread_mutex_unlock(&g_lock);

      limit = (st == VOICE_STATE_LISTENING) ? VOICE_WD_LISTEN_MS :
              (st == VOICE_STATE_THINKING)  ? VOICE_WD_THINK_MS :
              (st == VOICE_STATE_SPEAKING)  ? VOICE_WD_SPEAK_MS : 30000;

      if (el <= limit)
        {
          continue;
        }

      printf("[Voice] ⚠ 看门狗：状态 %d 已持续 %u ms（上限 %u），"
             "强制回到空闲（再点一次即可重新开始）\n", st, el, limit);

      ai_voice_stream_cancel();
      ai_voice_stream_finish();

      pthread_mutex_lock(&g_lock);
      g_gen++;
      g_cancel   = true;
      g_busy     = false;
      g_phase_tick = clock_systime_ticks();
      pthread_mutex_unlock(&g_lock);

      set_state(VOICE_STATE_IDLE);
    }

  return NULL;
}
```
