/****************************************************************************
 * Name: uart_putc
 ****************************************************************************/

static inline void uart_putchars(FAR uart_dev_t *dev,
                                 FAR const void *buf, size_t len)
{
  FAR const char *pbuf = buf;

  while (len > 0)
    {
      clock_t start = clock_systime_ticks();

      while (!uart_txready(dev))
        {
          /* 控制台主机不读走数据时 txready 会一直是 false，原来是死循环，
           * 而且调用点通常关着中断 —— 命中就是整个系统锁死。给控制台上限，
           * 等不到就丢掉剩下的输出。 */

          if (dev->isconsole &&
              clock_systime_ticks() - start >= MSEC2TICK(CONSOLE_TXWAIT_MSEC))
            {
              return;
            }
        }

      if (dev->ops->sendbuf)
        {
          ssize_t ret = uart_sendbuf(dev, pbuf, len);
          if (ret > 0)
            {
              pbuf += ret;
              len -= ret;
            }
        }
      else
        {
          uart_send(dev, *pbuf++);
          len--;
        }
    }
}

