 245: static void wifi_scan_start(void)
 246: {
 247:   pthread_t tid;
 248:   pthread_attr_t attr;
 249: 
 250:   if (s_scan_live)
 251:     {
 252:       return;
 253:     }
 254: 
 255:   s_scan_live = true;
 256:   s_scan_state = WSCAN_BUSY;
 257:   s_scan_gen++;
 258: 
 259:   pthread_attr_init(&attr);
 260:   pthread_attr_setstacksize(&attr, WIFI_THREAD_STACK);
 261:   if (pthread_create(&tid, &attr, wifi_scan_worker, NULL) == 0)
 262:     {
 263:       pthread_detach(tid);
 264:     }
 265:   else
 266:     {
 267:       s_scan_live = false;
 268:       s_scan_state = WSCAN_FAIL;
 269:       s_scan_gen++;
 270:     }
 271: 
 272:   pthread_attr_destroy(&attr);
 273: }
