static bool wifi_ping_ok(const char *ip, int wait_s)
{
  posix_spawn_file_actions_t fa;
  char *argv[8];
  pid_t pid;
  int status;
  char ws[8];
  snprintf(ws, sizeof(ws), "%d", wait_s);
